/* ========== 全局重置 ========== */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 100%; height: 100%; overflow: hidden;
  background: #000; color: #e8e8e8;
  font-family: "Segoe UI", "Microsoft YaHei", system-ui, sans-serif;
  user-select: none; cursor: default;
  touch-action: none;   /* 禁止浏览器默认触屏行为（滚动/缩放） */
  -webkit-touch-callout: none;
  overscroll-behavior: none;
}
body { background: #0a0a0a; }

.hidden { display: none !important; }

/* ========== 遮罩层 ========== */
.overlay {
  position: fixed; inset: 0;
  display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at center, rgba(20,25,35,0.92), rgba(0,0,0,0.97));
  z-index: 100; backdrop-filter: blur(4px);
}
.panel {
  text-align: center; padding: 48px 64px;
  background: linear-gradient(180deg, rgba(30,38,52,0.85), rgba(18,22,30,0.95));
  border: 1px solid rgba(255,180,60,0.25);
  border-radius: 12px;
  box-shadow: 0 0 60px rgba(255,170,40,0.08), inset 0 0 30px rgba(0,0,0,0.4);
  min-width: 380px;
}
.title {
  font-size: 56px; font-weight: 900; letter-spacing: 4px;
  color: #f5b53a;
  text-shadow: 0 0 20px rgba(245,181,58,0.4);
  margin-bottom: 6px;
}
.title span { color: #fff; }
.subtitle { color: #9aa4b2; letter-spacing: 6px; margin-bottom: 32px; font-size: 14px; }

.btn {
  display: inline-block; padding: 14px 56px; margin: 8px 0 24px;
  background: linear-gradient(180deg, #f5b53a, #d99020);
  color: #1a1208; border: none; border-radius: 6px;
  font-size: 18px; font-weight: 700; letter-spacing: 2px;
  cursor: pointer; transition: transform 0.1s, box-shadow 0.2s;
  box-shadow: 0 4px 16px rgba(245,181,58,0.3);
}
.btn:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(245,181,58,0.5); }
.btn:active { transform: translateY(0); }

.controls {
  margin-top: 16px; color: #c2cad6; font-size: 13px; line-height: 2;
  border-top: 1px solid rgba(255,255,255,0.08); padding-top: 16px;
}
.tip { margin-top: 14px; color: #6b7280; font-size: 12px; }

.stats { margin: 16px 0 24px; color: #c2cad6; line-height: 1.9; font-size: 15px; }
.stats b { color: #f5b53a; }

/* ========== HUD ========== */
#hud { position: fixed; inset: 0; pointer-events: none; z-index: 50; }

/* 准星（--gap 由 JS 按当前散布动态设置：静止收拢、移动张开） */
#crosshair {
  position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  --gap: 4px;
  pointer-events: none;
}
#crosshair span {
  position: absolute; background: #00ff88;
  box-shadow: 0 0 4px rgba(0,255,136,0.8);
}
#crosshair span:nth-child(1) { top: var(--gap); left: 50%; width: 2px; height: 7px; transform: translateX(-50%); }
#crosshair span:nth-child(2) { bottom: var(--gap); left: 50%; width: 2px; height: 7px; transform: translateX(-50%); }
#crosshair span:nth-child(3) { left: var(--gap); top: 50%; height: 2px; width: 7px; transform: translateY(-50%); }
#crosshair span:nth-child(4) { right: var(--gap); top: 50%; height: 2px; width: 7px; transform: translateY(-50%); }
#crosshair .dot {
  position: absolute; top: 50%; left: 50%;
  width: 2px; height: 2px; background: #00ff88;
  transform: translate(-50%, -50%); border-radius: 50%;
}
#crosshair.firing span { background: #ff4040; box-shadow: 0 0 6px rgba(255,64,64,0.9); }

/* 受击红屏 */
#damageFlash {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(200,20,20,0.55) 100%);
  opacity: 0; pointer-events: none; transition: opacity 0.4s;
}
#damageFlash.show { opacity: 1; transition: opacity 0.05s; }

/* 左下：血量护甲 */
#vitals {
  position: absolute; bottom: calc(24px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); left: 28px;
  display: flex; flex-direction: column; gap: 8px;
}
.vital { display: flex; align-items: center; gap: 10px; }
.vital .icon { font-size: 20px; width: 24px; text-align: center; }
.vital .bar {
  width: 200px; height: 14px;
  background: rgba(0,0,0,0.55); border: 1px solid rgba(255,255,255,0.15);
  border-radius: 3px; overflow: hidden;
}
.vital .fill { height: 100%; width: 100%; transition: width 0.25s; }
.fill.health { background: linear-gradient(90deg, #ff4040, #ff8060); }
.fill.armor { background: linear-gradient(90deg, #4a90e2, #7ec0ff); }
.vital span:not(.icon) { width: 36px; font-weight: 700; color: #fff; }

/* 右下：武器 */
#weaponHud {
  position: absolute; bottom: calc(24px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); right: 28px;
  text-align: right;
}
#weaponName { font-size: 14px; color: #9aa4b2; letter-spacing: 2px; }
#ammo { font-size: 38px; font-weight: 900; color: #fff; line-height: 1; }
#ammo .slash { color: #6b7280; font-weight: 400; margin: 0 4px; }
#ammoMag { color: #f5b53a; }
#weaponSlots { margin-top: 8px; display: flex; gap: 8px; justify-content: flex-end; }
.slot {
  padding: 3px 10px; font-size: 12px; color: #6b7280;
  border: 1px solid rgba(255,255,255,0.1); border-radius: 3px;
}
.slot.active { color: #f5b53a; border-color: rgba(245,181,58,0.5); background: rgba(245,181,58,0.08); }

/* 顶栏：得分 */
#topbar {
  position: absolute; top: calc(16px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 0;
  background: rgba(0,0,0,0.5); border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px; overflow: hidden;
}
.score-block {
  padding: 8px 24px; text-align: center;
  display: flex; flex-direction: column; align-items: center;
}
.score-block + .score-block { border-left: 1px solid rgba(255,255,255,0.08); }
.score-block .label { font-size: 11px; color: #9aa4b2; letter-spacing: 1px; }
.score-block .num { font-size: 22px; font-weight: 900; color: #fff; }
.score-block.enemy .num { color: #ff6060; }
.score-block.you .num { color: #00ff88; }
.score-block.center .label { font-size: 14px; color: #f5b53a; font-weight: 700; }

/* 击杀提示（左上角，位于武器切换按钮下方，避免与右上角小地图重叠） */
#killFeed {
  position: absolute; top: 140px; left: 28px;
  display: flex; flex-direction: column; gap: 6px;
  align-items: flex-start;
}
.kill-msg {
  background: rgba(0,0,0,0.6); padding: 6px 12px; border-radius: 4px;
  font-size: 13px; color: #ff6060;
  border-right: 3px solid #ff4040;
  animation: fadeOut 3s forwards;
}
.kill-msg .you { color: #00ff88; }
@keyframes fadeOut {
  0%, 70% { opacity: 1; transform: translateX(0); }
  100% { opacity: 0; transform: translateX(20px); }
}

/* 提示 toast */
#toast {
  position: absolute; bottom: 110px; left: 50%; transform: translateX(-50%);
  color: #f5b53a; font-size: 16px; font-weight: 700; letter-spacing: 2px;
  opacity: 0; transition: opacity 0.3s;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
}
#toast.show { opacity: 1; }

/* 点击锁定提示 */
#clickHint {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  text-align: center; color: #fff; font-size: 22px; font-weight: 700;
  text-shadow: 0 2px 8px rgba(0,0,0,0.9); pointer-events: none;
  background: rgba(0,0,0,0.4); padding: 20px 40px; border-radius: 8px;
}
#clickHint small { font-size: 12px; color: #9aa4b2; font-weight: 400; }

/* ========== 移动端虚拟控制 ========== */
#touchControls {
  position: absolute; inset: 0;
  pointer-events: none;   /* 让子元素单独控制点击 */
  z-index: 50;
}
#dpad {
  position: absolute; left: calc(16px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); bottom: calc(80px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px)));
  width: 130px; height: 130px;
  display: grid; grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 1fr 1fr 1fr;
  gap: 6px;
  pointer-events: auto;
}
.dpad-btn {
  background: rgba(255,255,255,0.15);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 10px;
  color: #fff; font-size: 20px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  touch-action: none; user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-shadow: 0 1px 2px rgba(0,0,0,0.6);
}
.dpad-btn:active, .dpad-btn.active {
  background: rgba(245,181,58,0.6);
  border-color: rgba(245,181,58,0.9);
}
.dpad-btn[data-key="KeyW"] { grid-column: 2; grid-row: 1; }
.dpad-btn[data-key="KeyA"] { grid-column: 1; grid-row: 2; }
.dpad-btn[data-key="KeyD"] { grid-column: 3; grid-row: 2; }
.dpad-btn[data-key="KeyS"] { grid-column: 2; grid-row: 3; }
#actionBtns {
  position: absolute; right: calc(16px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); bottom: calc(100px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px)));
  display: flex; flex-direction: column; gap: 10px;
  pointer-events: auto;
  align-items: center;
}
.act-btn {
  width: 56px; height: 56px;
  background: rgba(255,255,255,0.15);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 50%;
  color: #fff; font-size: 16px; font-weight: 700;
  touch-action: none; user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-shadow: 0 1px 2px rgba(0,0,0,0.6);
}
.act-btn:active, .act-btn.active {
  background: rgba(245,181,58,0.6);
  border-color: rgba(245,181,58,0.9);
}
/* FIRE 按钮特别突出 */
.fire-btn {
  width: 76px; height: 76px;
  background: rgba(220,60,60,0.75);
  border: 2px solid rgba(255,120,120,0.6);
  font-size: 18px;
}
.fire-btn:active, .fire-btn.active {
  background: rgba(255,80,80,0.95);
  border-color: rgba(255,200,200,0.9);
}

/* 触屏设备自动显示虚拟控制 */
@media (hover: none) and (pointer: coarse) {
  #touchControls:not(.hidden) { display: block; }
}

/* 小屏设备 / 容器内始终显示虚拟控制（兜底，阈值与 main.js 一致） */
@media (max-width: 1024px) {
  #touchControls:not(.hidden) { display: block; }
}

/* 左上：武器切换 + 暂停 */
#topControls {
  position: absolute; left: calc(16px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); top: calc(80px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  display: flex; flex-direction: row; gap: 8px;
  pointer-events: auto;
  z-index: 50;
}
.top-btn {
  width: 44px; height: 44px;
  background: rgba(255,255,255,0.15);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 8px;
  color: #fff; font-size: 18px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  touch-action: none; user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-shadow: 0 1px 2px rgba(0,0,0,0.6);
}
.top-btn:active, .top-btn.active {
  background: rgba(245,181,58,0.6);
  border-color: rgba(245,181,58,0.9);
}

/* ========== 小地图 ========== */
#minimapWrap {
  position: absolute; right: calc(16px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); top: calc(80px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  width: 160px; height: 160px;
  background: rgba(0,0,0,0.65);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 8px;
  z-index: 40;
  overflow: hidden;
}
#minimap {
  width: 100%; height: 100%;
  display: block;
}

/* ========== 横竖屏自适应布局 ========== */

/* ---- 竖屏（手机竖拿）---- */
@media (orientation: portrait) {
  .panel {
    min-width: 0;
    width: min(440px, calc(100vw - 24px));
    padding: 28px 20px;
  }
  .title { font-size: 40px; }
  .subtitle { font-size: 12px; margin-bottom: 20px; }
  .btn { padding: 12px 40px; font-size: 16px; }
  .controls { font-size: 12px; }
  .tip { font-size: 11px; }

  /* 顶栏：收窄居中 */
  #topbar {
    top: calc(8px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
    transform: translateX(-50%) scale(0.82);
    transform-origin: top center;
  }
  .score-block { padding: 6px 14px; }
  .score-block .num { font-size: 18px; }
  .score-block.center .label { font-size: 12px; }

  /* 左上：武器切换（缩窄，避开顶栏） */
  #topControls {
    left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px)));
    top: calc(56px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
    gap: 6px;
  }
  .top-btn { width: 40px; height: 40px; font-size: 16px; }

  /* 右上：小地图缩小 */
  #minimapWrap {
    width: 108px; height: 108px;
    right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px)));
    top: calc(56px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  }

  /* 左下：血量护甲收窄 */
  #vitals { left: 12px; bottom: calc(10px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 6px; }
  .vital .bar { width: 120px; height: 12px; }
  .vital span:not(.icon) { width: 30px; font-size: 14px; }
  .vital .icon { font-size: 16px; width: 20px; }

  /* 右下：武器弹药收窄，为动作键让位 */
  #weaponHud { right: 12px; bottom: calc(10px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); }
  #ammo { font-size: 28px; }
  #weaponName { font-size: 12px; }
  #weaponSlots { gap: 5px; }
  .slot { padding: 2px 7px; font-size: 10px; }

  /* D-pad 缩小、上移到血量条上方 */
  #dpad {
    width: 108px; height: 108px;
    left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px)));
    bottom: calc(96px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px)));
    gap: 4px;
  }
  .dpad-btn { font-size: 16px; border-radius: 8px; }

  /* 动作键（含 FIRE）上移，避开武器 HUD */
  #actionBtns {
    right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px)));
    bottom: calc(150px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px)));
    gap: 8px;
  }
  .act-btn { width: 48px; height: 48px; font-size: 14px; }
  .fire-btn { width: 64px; height: 64px; font-size: 16px; }

  #toast { bottom: 170px; font-size: 14px; }
  #killFeed { top: 104px; left: 12px; }
}

/* ---- 横屏低高度（手机横拿，高度 ≤ 520px）---- */
@media (orientation: landscape) and (max-height: 520px) {
  .panel {
    min-width: 0;
    width: min(560px, 92vw);
    padding: 20px 28px;
  }
  .title { font-size: 34px; }
  .subtitle { font-size: 12px; margin-bottom: 14px; }
  .btn { padding: 10px 36px; font-size: 15px; margin-bottom: 14px; }
  .controls { font-size: 11px; line-height: 1.8; }
  .tip { font-size: 11px; }

  #topbar { top: calc(6px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); transform: translateX(-50%) scale(0.78); transform-origin: top center; }
  .score-block { padding: 5px 12px; }
  .score-block .num { font-size: 16px; }
  .score-block.center .label { font-size: 11px; }

  #topControls { left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); top: calc(48px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); gap: 6px; }
  .top-btn { width: 36px; height: 36px; font-size: 14px; }

  #minimapWrap { width: 96px; height: 96px; right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); top: calc(48px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }

  #vitals { left: 10px; bottom: calc(8px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 5px; }
  .vital .bar { width: 110px; height: 10px; }
  .vital span:not(.icon) { width: 28px; font-size: 13px; }
  .vital .icon { font-size: 14px; width: 18px; }

  #weaponHud { right: calc(12px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); bottom: auto; top: calc(150px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }
  #ammo { font-size: 24px; }
  #weaponName { font-size: 11px; }
  #weaponSlots { gap: 5px; }
  .slot { padding: 2px 6px; font-size: 10px; }

  #dpad { width: 100px; height: 100px; left: calc(10px + var(--safe-area-inset-left, env(safe-area-inset-left, 0px))); bottom: calc(56px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 4px; }
  .dpad-btn { font-size: 15px; border-radius: 8px; }

  #actionBtns { right: calc(10px + var(--safe-area-inset-right, env(safe-area-inset-right, 0px))); bottom: calc(8px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 6px; }
  .act-btn { width: 44px; height: 44px; font-size: 13px; }
  .fire-btn { width: 58px; height: 58px; font-size: 15px; }

  #toast { bottom: 150px; font-size: 13px; }
  #killFeed { top: 92px; left: 10px; }
}

/* ---- 极端小屏兜底（老机型/折叠屏）：在竖屏/矮横屏基础上进一步压缩 ---- */
@media (orientation: portrait) and (max-width: 340px) {
  #dpad { width: 96px; height: 96px; bottom: calc(88px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); }
  .dpad-btn { font-size: 14px; }
  #actionBtns { bottom: calc(140px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); gap: 6px; }
  .act-btn { width: 44px; height: 44px; font-size: 13px; }
  .fire-btn { width: 58px; height: 58px; font-size: 15px; }
  #vitals { left: 8px; }
  .vital .bar { width: 100px; }
  #weaponHud { right: 8px; }
  #ammo { font-size: 24px; }
  #minimapWrap { width: 92px; height: 92px; }
  #topControls { gap: 4px; }
  .top-btn { width: 34px; height: 34px; font-size: 14px; }
}

@media (orientation: landscape) and (max-height: 380px) {
  #dpad { width: 88px; height: 88px; bottom: calc(48px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))); }
  .dpad-btn { font-size: 13px; }
  #actionBtns { gap: 4px; }
  .act-btn { width: 40px; height: 40px; font-size: 12px; }
  .fire-btn { width: 52px; height: 52px; font-size: 14px; }
  #vitals { gap: 4px; }
  .vital .bar { width: 92px; height: 9px; }
  #weaponHud { top: calc(138px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }
  #ammo { font-size: 21px; }
  #minimapWrap { width: 84px; height: 84px; }
  #topControls { top: calc(42px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px))); }
  .top-btn { width: 32px; height: 32px; font-size: 13px; }
  #killFeed { top: 86px; }
  #toast { bottom: 130px; font-size: 12px; }
}
